"""
The object mapping related add-ons.
"""
from typing import Type, Any, Optional

def reconfigure_object_mapping(cls: Type[Any], objectMappingDefinitions:Optional[dict] , idMap:Optional[dict], version:Optional[str]):
    """
    Generic method to reconfig the id and other attributes in the ui element mapping definitions, with given object definition,
    id_map and version. If objectMappingDefinitions is empty or None, then use idMap only, and vice versa.
    After this function is called, the attributes of the class are overriden by what is provided by the parameters.

    :params: cls, the UI object mapping class
             objectMappingDefinitions (Optional[dict]),  ui element mapping definitions
             idMap (Optional[dict]), version dependent id maps,
             version (Optional[str]), version string(e.g.  "vern", ..., "ver2",  or "ver1", or a version number, that is used in id_map)

    Note: the recommended versions are typically vern, ...,ver2, ver1, where vern is the latest version. But you can define them other way.
          And you may provide only one version for idMap. version is only needed when idMap is not None.

    Sample data:

    _object_mapping_definitions = {
        "Treament_session_pane_on_main": {
            "type": "newType"
        },
        "insertSessionsTab_Insert_Sessions_Button": {
            "type": "Button",
            "text":  objectmaphelper.Wildcard("Insert Sessions For*")
        },
        "insertSessionsTab_Schedule_All_Fields_Button": {
            "type": "Button",
            "text": "Schedule All Fields >> "
        },
        "insertSessionsTab_Course_One_Prescription_Dropdown": {
            "type": "Pane",
            "text": "Add"
        },
        "insertSessionsTab_Start_Date_TextBox": {
            "type": "Edit"
        }
    }

    _id_map = {
        "ver2": {
                "Treament_session_pane_on_main": 16870,
                "insertSessionsTab_Insert_Sessions_Button": 16825,
                "insertSessionsTab_Schedule_All_Fields_Button":16827,
                "insertSessionsTab_Course_One_Prescription_Dropdown": 16817,
                "insertSessionsTab_Start_Date_TextBox": 16894
        },
        "ver1: {
                "Treament_session_pane_on_main": 16869,
                "insertSessionsTab_Insert_Sessions_Button": 16824,
                "insertSessionsTab_Schedule_All_Fields_Button": 16826,
                "insertSessionsTab_Course_One_Prescription_Dropdown": 16816,
                "insertSessionsTab_Start_Date_TextBox": 16893
        }
    }

    then you can use it any time you'd like to define or re-define the object mapping by a call in your code like below:

    reconfigure_object_mapping(cls=ROTreat, objectMappingDefinitions=_object_mapping_definitions, idMap=_id_map, version="ver2")
    """

    if (not objectMappingDefinitions) and (not idMap):
        print("No object mapping introduced.")
        return

    if objectMappingDefinitions:
        if isinstance(objectMappingDefinitions, dict):
            for name, attrs in objectMappingDefinitions.items():
                element_attrs = getattr(cls, name)
                element_attrs.update(attrs)
                if idMap and isinstance(idMap, dict):
                    element_attrs["id"] = idMap[version][name]
                setattr(cls, name, element_attrs)
    elif idMap and isinstance(idMap, dict):
        for name, _ in idMap[next(iter(idMap))].items():
            element_attrs = getattr(cls, name)
            element_attrs["id"] = idMap[version][name]
            setattr(cls, name, element_attrs)